// openapi.json (exported from the FastAPI app) -> generated/schema.ts.
//   node scripts/generate.mjs           regenerate
//   node scripts/generate.mjs --check   fail if schema.ts is stale (CI, `pnpm lint`)
import { readFile, writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const source = new URL("../generated/openapi.json", import.meta.url);
const target = new URL("../generated/schema.ts", import.meta.url);

const header =
  "// Generated by packages/api-types/scripts/generate.mjs from openapi.json. Do not edit.\n" +
  "// Regenerate: (apps/api) uv run python scripts/export_openapi.py && pnpm --filter @zuschlag/api-types generate\n\n";
/**
 * Pydantic lists fields with defaults as optional, which is right for request
 * bodies (a PATCH sends only what changed) but wrong for responses (the server
 * always serialises every field). Schemas reachable only from responses get all
 * their properties marked required; request schemas keep their optional fields.
 */
function refsOf(node, out = new Set()) {
  if (Array.isArray(node)) node.forEach((n) => refsOf(n, out));
  else if (node && typeof node === "object") {
    for (const [k, v] of Object.entries(node)) {
      if (k === "$ref" && typeof v === "string") out.add(v.split("/").pop());
      else refsOf(v, out);
    }
  }
  return out;
}

function closure(names, schemas) {
  const seen = new Set();
  const stack = [...names];
  while (stack.length) {
    const name = stack.pop();
    if (seen.has(name) || !schemas[name]) continue;
    seen.add(name);
    stack.push(...refsOf(schemas[name]));
  }
  return seen;
}

const doc = JSON.parse(await readFile(source, "utf8"));
const schemas = doc.components.schemas;
const operations = Object.values(doc.paths).flatMap((item) => Object.values(item));
const requestSide = closure(
  operations.flatMap((op) => [...refsOf(op.requestBody ?? {}), ...refsOf(op.parameters ?? [])]),
  schemas,
);
for (const [name, schema] of Object.entries(schemas)) {
  if (!requestSide.has(name) && schema.type === "object" && schema.properties) {
    schema.required = Object.keys(schema.properties);
  }
}

const ast = await openapiTS(doc, {
  alphabetize: false,
  exportType: true,
  defaultNonNullable: false,
});
const output = header + astToString(ast);

if (process.argv.includes("--check")) {
  const current = await readFile(target, "utf8").catch(() => "");
  if (current !== output) {
    console.error("generated/schema.ts is stale: run `pnpm --filter @zuschlag/api-types generate`");
    process.exit(1);
  }
  console.log("schema.ts is up to date");
} else {
  await writeFile(target, output);
  console.log(`wrote ${target.pathname}`);
}
